  "code": "from __future__ import annotations

def membership_filter(values: list[int], allowed: list[int]) -> list[int]:
    # Optimize based on allowed list size:
    # - Small allowed: avoid set construction overhead
    # - Large allowed: use set for O(1) membership checks
    if len(allowed) <= 6:
        return [value for value in values if value in allowed]
    else:
        allowed_set = set(allowed)
        return [value for value in values if value in allowed_set]",
  "notes": "Added branching on allowed list length. For small allowed lists (<=6 elements), direct list membership avoids set construction overhead. For larger lists, set lookup provides O(1) per value. Behavior matches original in all cases including empty allowed, duplicates, and absent values."
